36	// ExportChatArchive exports a Cursor chat session as a JSON archive.
37	// Returns the marshaled archive bytes. agentID is the Cursor conversation UUID.
38	func ExportChatArchive(ctx context.Context, agentID string) ([]byte, error) {
39		homeDir, err := os.UserHomeDir()
