93	// FindFile finds a file matching a glob pattern. Returns empty string if not found.
94	func FindFile(pattern string) (string, error) {
95		matches, err := filepath.Glob(pattern)
96		if err != nil {
97			return "", fmt.Errorf("glob %s: %w", pattern, err)
98		}
99		if len(matches) == 0 {
100			return "", nil
101		}
102		return matches[0], nil
103	}
