105	// ExportDB reads all data from a Cursor store.db file.
106	func ExportDB(ctx context.Context, dbPath string) (StoreData, error) {
107		db, err := sql.Open("sqlite", dbPath)
108		if err != nil {
109			return StoreData{}, fmt.Errorf("opening database: %w", err)
110		}
111		defer db.Close()
112	
113		// Flush WAL to main database file
114		if _, err := db.ExecContext(ctx, "PRAGMA wal_checkpoint(PASSIVE)"); err != nil {
115			return StoreData{}, fmt.Errorf("WAL checkpoint: %w", err)
116		}
117	
118		meta := make(map[string]string)
119		metaRows, err := db.QueryContext(ctx, "SELECT key, value FROM meta")
120		if err != nil {
121			return StoreData{}, fmt.Errorf("querying meta: %w", err)
122		}
123		defer metaRows.Close()
124		for metaRows.Next() {
125			var key, value string
126			if err := metaRows.Scan(&key, &value); err != nil {
127				return StoreData{}, fmt.Errorf("scanning meta row: %w", err)
128			}
129			meta[key] = value
130		}
131		if err := metaRows.Err(); err != nil {
132			return StoreData{}, fmt.Errorf("iterating meta rows: %w", err)
133		}
134	
135		blobs := make(map[string]string)
136		blobRows, err := db.QueryContext(ctx, "SELECT id, data FROM blobs")
137		if err != nil {
138			return StoreData{}, fmt.Errorf("querying blobs: %w", err)
139		}
140		defer blobRows.Close()
141		for blobRows.Next() {
142			var id string
143			var data []byte
144			if err := blobRows.Scan(&id, &data); err != nil {
145				return StoreData{}, fmt.Errorf("scanning blob row: %w", err)
146			}
147			blobs[id] = base64.StdEncoding.EncodeToString(data)
148		}
149		if err := blobRows.Err(); err != nil {
150			return StoreData{}, fmt.Errorf("iterating blob rows: %w", err)
151		}
152	
153		return StoreData{Meta: meta, Blobs: blobs}, nil
154	}
