156	// ReadTranscriptFile reads a JSONL transcript file and returns the parsed entries.
157	func ReadTranscriptFile(path string) ([]json.RawMessage, error) {
158		data, err := os.ReadFile(path) //nolint:gosec // path is constructed from glob results, not user input
159		if err != nil {
160			return nil, fmt.Errorf("reading transcript file: %w", err)
161		}
162	
163		var entries []json.RawMessage
164		dec := json.NewDecoder(bytes.NewReader(data))
165		for dec.More() {
166			var raw json.RawMessage
167			if err := dec.Decode(&raw); err != nil {
168				return nil, fmt.Errorf("decoding transcript line: %w", err)
169			}
170			entries = append(entries, raw)
171		}
172		return entries, nil
173	}
