	}

	archive := ChatArchive{
		Format:  archiveFormat,
		Version: archiveVersion,
		AgentID: agentID,
		DBPath:  dbPath,
	}

	if archive.DBBytes, err = readBase64(dbPath); err != nil {
		return nil, fmt.Errorf("reading store.db: %w", err)
	}
	if wal, err := readBase64(dbPath + "-wal"); err == nil {
