290	func (s *ManualCommitStrategy) Rewind(ctx context.Context, w, errW io.Writer, point RewindPoint) error {
291		repo, err := OpenRepository(ctx)
292		if err != nil {
293			return fmt.Errorf("failed to open git repository: %w", err)
294		}
295	
296		// Get the checkpoint commit
297		commitHash := plumbing.NewHash(point.ID)
298		commit, err := repo.CommitObject(commitHash)
299		if err != nil {
300			return fmt.Errorf("failed to get commit: %w", err)
301		}
302	
303		tree, err := commit.Tree()
304		if err != nil {
305			return fmt.Errorf("failed to get tree: %w", err)
306		}
307	
308		// Reset the shadow branch to the rewound checkpoint
309		// This ensures the next checkpoint will only include prompts from this point forward
310		if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
311			// Log warning but don't fail - file restoration is the primary operation
312			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
313		}
314	
315		// Load session state to get untracked files that existed at session start
316		sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
317		var preservedUntrackedFiles map[string]bool
318		if hasSessionTrailer {
319			state, stateErr := s.loadSessionState(ctx, sessionID)
320			if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
321				preservedUntrackedFiles = make(map[string]bool)
322				for _, f := range state.UntrackedFilesAtStart {
323					preservedUntrackedFiles[f] = true
324				}
325			}
326		}
327	
328		// Build set of files in the checkpoint tree (excluding metadata)
329		checkpointFiles := make(map[string]bool)
330		err = tree.Files().ForEach(func(f *object.File) error {
331			if err := ctx.Err(); err != nil {
332				return err //nolint:wrapcheck // Propagating context cancellation
333			}
334			if !strings.HasPrefix(f.Name, entireDir) {
335				checkpointFiles[f.Name] = true
336			}
337			return nil
338		})
339		if err != nil {
340			return fmt.Errorf("failed to list checkpoint files: %w", err)
341		}
342	
343		// Get HEAD tree to identify tracked files
344		head, err := repo.Head()
345		if err != nil {
346			return fmt.Errorf("failed to get HEAD: %w", err)
347		}
348		headCommit, err := repo.CommitObject(head.Hash())
349		if err != nil {
350			return fmt.Errorf("failed to get HEAD commit: %w", err)
351		}
352		headTree, err := headCommit.Tree()
353		if err != nil {
354			return fmt.Errorf("failed to get HEAD tree: %w", err)
355		}
356	
357		// Build set of files tracked in HEAD
358		trackedFiles := make(map[string]bool)
359		//nolint:errcheck // Error is not critical for rewind
360		_ = headTree.Files().ForEach(func(f *object.File) error {
361			if err := ctx.Err(); err != nil {
362				return err //nolint:wrapcheck // Propagating context cancellation
363			}
364			trackedFiles[f.Name] = true
365			return nil
366		})
367	
368		// Get repository root to walk from there
369		repoRoot, err := paths.WorktreeRoot(ctx)
370		if err != nil {
371			repoRoot = "." // Fallback to current directory
372		}
373	
374		// Open os.Root at repo root for traversal-resistant file operations.
375		// Defense-in-depth: paths come from git tree objects (trusted) but we
376		// still scope operations to prevent any escape from the repo root.
377		repoRootHandle, err := os.OpenRoot(repoRoot)
378		if err != nil {
379			return fmt.Errorf("failed to open repo root: %w", err)
380		}
381		defer repoRootHandle.Close()
382	
383		// Find and delete untracked files that aren't in the checkpoint.
384		// Uses git ls-files to only consider non-ignored files, avoiding walks through
385		// large ignored directories like node_modules/.
386		untrackedNow, err := collectUntrackedFiles(ctx)
387		if err != nil {
388			// Non-fatal - continue with restoration
389			fmt.Fprintf(errW, "Warning: error listing untracked files: %v\n", err)
390		}
391		for _, relPath := range untrackedNow {
392			// If file is in checkpoint, it will be restored
393			if checkpointFiles[relPath] {
394				continue
395			}
396	
397			// If file is tracked in HEAD, don't delete (user's committed work)
398			if trackedFiles[relPath] {
399				continue
400			}
401	
402			// If file existed at session start, preserve it (untracked user files)
403			if preservedUntrackedFiles[relPath] {
404				continue
405			}
406	
407			// File is untracked and not in checkpoint - delete it via os.Root
408			if removeErr := osroot.Remove(repoRootHandle, relPath); removeErr == nil {
409				fmt.Fprintf(w, "  Deleted: %s\n", relPath)
410			}
411		}
412	
413		// Restore files from checkpoint
414		err = tree.Files().ForEach(func(f *object.File) error {
415			if err := ctx.Err(); err != nil {
416				return err //nolint:wrapcheck // Propagating context cancellation
417			}
418			// Skip metadata directories - these are for checkpoint storage, not working dir
419			if strings.HasPrefix(f.Name, entireDir) {
420				return nil
421			}
422	
423			contents, err := f.Contents()
424			if err != nil {
425				return fmt.Errorf("failed to read file %s: %w", f.Name, err)
426			}
427	
428			// Ensure directory exists (MkdirAll not available on os.Root)
429			absPath := filepath.Join(repoRoot, f.Name)
430			dir := filepath.Dir(absPath)
431			if dir != "." {
432				//nolint:gosec // G301: Need 0o755 for user directories during rewind
433				if err := os.MkdirAll(dir, 0o755); err != nil {
434					return fmt.Errorf("failed to create directory %s: %w", dir, err)
435				}
436			}
437	
438			// Write file with appropriate permissions via os.Root
439			var perm os.FileMode = 0o644
440			if f.Mode == filemode.Executable {
441				perm = 0o755
442			}
443			if err := osroot.WriteFile(repoRootHandle, f.Name, []byte(contents), perm); err != nil {
444				return fmt.Errorf("failed to write file %s: %w", f.Name, err)
445			}
446	
447			fmt.Fprintf(w, "  Restored: %s\n", f.Name)
448			return nil
449		})
450		if err != nil {
451			return fmt.Errorf("failed to iterate tree files: %w", err)
452		}
453	
454		fmt.Fprintln(w)
455		if len(point.ID) >= 7 {
456			fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID[:7])
457		} else {
458			fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID)
459		}
460		fmt.Fprintln(w)
461	
462		return nil
463	}
